xql_query:
// ============================================================
// Rule: MS_CrossTenant Partner Added Success
// Vendor: Microsoft EntraID
// Objective:
// Detect activity associated with MS_CrossTenant Partner Added Success.
// Severity: SEV_050_CRITICAL
// Category: INFILTRATION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0005 - Defense Evasion
// Technique: T1484 - Domain Policy Modification
// Technique: T1484.002 - Domain Policy Modification: Domain Trust Modification

// Configuração inicial: comparações não diferenciam maiúsculas/minúsculas
// Objetivo: evitar perda de eventos por variações de caixa em strings (ex.: operation_name_orig / displayName)
config case_sensitive = false

// Fonte de dados: Cloud Audit Logs (Azure AD)
// O dataset 'cloud_audit_logs' centraliza logs de auditoria de cloud providers.
// Aqui filtramos especificamente por 'azure_ad_audit_logs'.
| dataset = cloud_audit_logs

// Filtro: limita aos eventos de auditoria do Azure AD relacionados a cross-tenant access
// "Add a partner to cross-tenant access setting" indica inclusão de parceiro/tenant em configurações de acesso cross-tenant
| filter log_name = "azure_ad_audit_logs"
| filter operation_name_orig contains "Add a partner to cross-tenant access setting"

// Extração: identifica o executor (quem iniciou a mudança) a partir do raw_log (JSON)
// - initiatedBy_userPrincipalName: UPN do usuário (ex.: nome@dominio)
// - initiatedBy_userID: objectId do usuário no Entra ID
// - initiatedBy_IpAddress: IP de origem do executor
| alter
    initiatedBy_userPrincipalName = json_extract(raw_log, "$.properties.initiatedBy.user.userPrincipalName"),
    initiatedBy_userID            = json_extract(raw_log, "$.properties.initiatedBy.user.id"),
    initiatedBy_IpAddress         = json_extract(raw_log, "$.properties.initiatedBy.user.ipAddress")

// Extração: captura qual propriedade foi modificada no targetResources[0].modifiedProperties[0]
// Observação: o índice (0) pode variar conforme o evento; este caminho atende o formato mais comum.
// Aqui usamos displayName para validar se a modificação foi no tenantId.
| alter
    Modified_Properties_displayName = json_extract(raw_log, "$.properties.targetResources.0.modifiedProperties.0.displayName")

// Filtro: garante que a propriedade alterada está relacionada ao "tenantId" (parceiro/tenant adicionado)
| filter Modified_Properties_displayName contains "tenantId"

// Extração: valores antigo e novo do tenantId (antes/depois da alteração)
| alter
    oldTenantValue = json_extract(raw_log, "$.properties.targetResources.0.modifiedProperties.0.oldValue"),
    newTenantValue = json_extract(raw_log, "$.properties.targetResources.0.modifiedProperties.0.newValue")

// Filtro: considera somente mudanças bem-sucedidas (reduz ruído)
| filter operation_status = "Success"

// Saída final: campos recomendados para alerta/correlação e auditoria
| fields
    _time,                           // Timestamp do evento
    event_id,                        // Identificador do evento
    operation_name_orig,             // Operação executada no Azure AD
    operation_status,                // Status (Success/Failure)
    initiatedBy_userPrincipalName,   // UPN do executor
    initiatedBy_userID,              // ID do executor
    initiatedBy_IpAddress,           // IP do executor
    referenced_resource as Federated_Domain, // Recurso/referência associada (ex.: domínio/tenant federado, quando disponível)
    newTenantValue,                  // Novo tenantId configurado
    oldTenantValue,                  // Antigo tenantId (se existir)
    raw_log                          // Payload bruto (evidência para investigação)
